  if (bytes.length >= 12 && bytes.subarray(0, 4).toString('ascii') === 'RIFF' && bytes.subarray(8, 12).toString('ascii') === 'WEBP') {
    return 'image/webp';
  }
  if (bytes.length >= 3 && bytes.subarray(0, 3).toString('ascii') === 'GIF') {
    return 'image/gif';
  }
  return null;
}

