{"kind":"tool","id":"gTjP5WGNxsw","toolName":"write_file","input":{"path":".env.example","instructions":"Point the env template at the free router and the OpenRouter image API.","content":"# --- Cron protection -------------------------------------------------------
# Long random string. Vercel sends it automatically to /api/cron as a bearer token.
CRON_SECRET=

# --- Text model (OpenRouter) ----------------------------------------------
OPENROUTER_API_KEY=
# openrouter/free is a router, not a version: it picks a zero-cost model per
# request, so it never goes stale the way a pinned slug does.
# Any slug from https://openrouter.ai/models also works here.
OPENROUTER_MODEL=openrouter/free
# Reasoning models bill thinking tokens against this budget; keep it generous
# or the JSON reply gets truncated. Raise it if a long post gets cut off.
OPENROUTER_MAX_TOKENS=4000
# high | medium | low. Lower effort leaves more of the budget for the post.
# (Models with mandatory reasoning cannot be turned off.)
OPENROUTER_REASONING_EFFORT=low

# --- Images (OpenRouter Image API) ----------------------------------------
# openrouter (default) | cloudflare
IMAGE_PROVIDER=openrouter
# Blank = the newest text-to-image model in OpenRouter's live catalog, resolved
# on each cold start. Pin a slug here only if you want a specific look.
OPENROUTER_IMAGE_MODEL=
