const IMAGES_URL = 'https://openrouter.ai/api/v1/images';

// Cloudflare worker image generation from automation.py logic
export const DEFAULT_IMAGE_ASPECT_RATIO = '16:9';

// Providers: 'cloudflare' uses IMAGE_API_URL + IMAGE_API_KEY, 'openrouter' uses OpenRouter Image API
export const IMAGE_PROVIDERS = ['cloudflare', 'openrouter'];

/** Resolve which image provider to use. Defaults to 'cloudflare' for backwards compatibility. */
export function resolveImageProvider(env = process.env) {
  const raw = optionalEnv(env, 'IMAGE_PROVIDER', 'cloudflare').toLowerCase();
  if (IMAGE_PROVIDERS.includes(raw)) return raw;
  throw new Error(`IMAGE_PROVIDER=${raw} is not supported. Use ${IMAGE_PROVIDERS.join(' or ')}.`);
}

/** Fallback: OpenRouter Image API (same shape as the new path). */
export class ImageError extends Error {
  constructor(message, status = 502) {
    super(message);
    this.name = 'ImageError';
    this.statusCode = status;
  }
}

/**
 * POST <IMAGE_API_URL>  Authorization: Bearer <key>  { prompt }
 * Handles a raw image body, a base64 JSON payload, or a JSON payload with an image URL.
 * Same logic as the original automation.py port.
 */
export async function generateImageFromWorker({ prompt, url, apiKey, timeoutMs = 90000 }) {
  if (!url) throw new ImageError('Missing IMAGE_API_URL (required when IMAGE_PROVIDER=cloudflare).');
  if (!apiKey) throw new ImageError('Missing IMAGE_API_KEY (required when IMAGE_PROVIDER=cloudflare).');

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        Accept: 'image/*, application/json',
      },
      body: JSON.stringify({ prompt }),
      signal: controller.signal,
    });

    const contentTypeHeader = (res.headers.get('content-type') || '').toLowerCase();

    if (!res.ok) {
      const detail = (await res.text().catch(() => '')).slice(0, 400);
      throw new ImageError(`Image API failed (${res.status}): ${detail}`);
    }

    if (!contentTypeHeader.includes('json')) {
      const bytes = Buffer.from(await res.arrayBuffer());
      if (!bytes.length) throw new ImageError('Image API returned an empty body.');
      return {
        bytes,
        contentType: sniffContentType(bytes) || contentTypeHeader.split(';')[0] || 'image/png',
        model: null,
      };
    }

    const data = await res.json();
    const base64 = pickBase64(data);

    if (base64) {
      const bytes = Buffer.from(stripDataUrl(base64), 'base64');
      if (!bytes.length) throw new ImageError('Image API returned empty base64 image data.');
      return {
        bytes,
        contentType: sniffContentType(bytes) || 'image/png',
        model: null,
      };
    }

    const imageUrl = pickUrl(data);
    if (imageUrl) {
      const imageRes = await fetch(imageUrl, { signal: controller.signal });
      if (!imageRes.ok) throw new ImageError(`Could not download generated image (${imageRes.status}).`);
      const bytes = Buffer.from(await imageRes.arrayBuffer());
      if (!bytes.length) throw new ImageError('Generated image download was empty.');
      return { bytes, contentType: sniffContentType(bytes) || 'image/png', model: null };
    }

    throw new ImageError(`Image API returned JSON without image data: ${JSON.stringify(data).slice(0, 300)}`);
  } catch (err) {
    if (err instanceof ImageError) throw err;
    if (err?.name === 'AbortError') throw new ImageError(`Image API timed out after ${timeoutMs}ms.`);
    throw new ImageError(`Image API request failed: ${err?.message || err}`);
  } finally {
    clearTimeout(timer);
  }
}

/**
 * OpenRouter Image API path (kept for reference/optional use).
 * POST https://openrouter.ai/api/v1/images  Authorization: Bearer <key>  { model, prompt, n, aspect_ratio }
 */
export async function generateImageWithOpenRouter({ prompt, model, apiKey, aspectRatio = DEFAULT_IMAGE_ASPECT_RATIO, supportsAspectRatio = true, siteUrl, timeoutMs = 150000 }) {
  if (!apiKey) throw new ImageError('Missing OPENROUTER_API_KEY.');
  if (!model) throw new ImageError('No OpenRouter image model resolved.');
  if (!prompt) throw new ImageError('Refusing to generate an image without a prompt.');

  const body = { model, prompt, n: 1 };
  if (supportsAspectRatio && aspectRatio) body.aspect_ratio = aspectRatio;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(IMAGES_URL, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        Accept: 'application/json',
        ...(siteUrl ? { 'HTTP-Referer': siteUrl } : {}),
        'X-Title': 'LinkedIn Auto Poster',
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });

    if (!res.ok) {
      const detail = (await res.text().catch(() => '')).slice(0, 400);
      const hint = res.status === 401 ? ' Check OPENROUTER_API_KEY.' : '';
      throw new ImageError(`OpenRouter image API ${res.status} (model=${model}): ${detail}${hint}`);
    }

    const data = await res.json();
    const base64 = pickBase64(data);

    if (base64) {
      const bytes = Buffer.from(stripDataUrl(base64), 'base64');
      if (!bytes.length) throw new ImageError('OpenRouter returned empty image data.');
      return {
        bytes,
        contentType: data?.data?.[0]?.media_type || sniffContentType(bytes) || 'image/png',
        model,
      };
    }

    const imageUrl = pickUrl(data);
    if (imageUrl) {
      const imageRes = await fetch(imageUrl, { signal: controller.signal });
      if (!imageRes.ok) throw new ImageError(`Could not download the generated image (${imageRes.status}).`);
      const bytes = Buffer.from(await imageRes.arrayBuffer());
      if (!bytes.length) throw new ImageError('Generated image download was empty.');
      return { bytes, contentType: sniffContentType(bytes) || 'image/png', model };
    }

    throw new ImageError(`OpenRouter image API returned no image (model=${model}): ${JSON.stringify(data).slice(0, 300)}`);
  } catch (err) {
    if (err instanceof ImageError) throw err;
    if (err?.name === 'AbortError') throw new ImageError(`OpenRouter image API timed out after ${timeoutMs}ms (model=${model}).`);
    throw new ImageError(`OpenRouter image request failed (model=${model}): ${err?.message || err}`);
  } finally {
    clearTimeout(timer);
  }
